async function piBookingPageLooksLoggedIn(page) {
  const url = page.url();
  if (/account\.booking\.com|sign-in|\/login/i.test(url)) return false;
  if (await page.locator('input[type="password"]:visible, #loginname:visible, input[name="loginname"]:visible').count()) return false;
  try {
    const u = new URL(url);
    if (u.hostname === 'admin.booking.com' && /hoteladmin|extranet|groups/i.test(u.pathname)) return true;
  } catch (eUrl) {}
  return false;
}
async function piBookingSaveLiveSession(job) {
  if (!job || !job.context || !job.page) return false;
  if (!(await piBookingPageLooksLoggedIn(job.page))) return false;
  const state = await job.context.storageState();
  const cookies = (state && Array.isArray(state.cookies)) ? state.cookies : [];
  if (cookies.length < 3) return false;
  await piSavePortalSession('booking', state, job.by || 'in-app-connect');
  job._piSessionSaved = true;
  job.updatedAt = Date.now();
  return true;
}
async function piBookingFinishAndSave(job) {
  const page = job.page;
  const context = job.context;
  await page.waitForTimeout(800);
  if (!(await piBookingPageLooksLoggedIn(page))) {
    throw new Error('Booking.com is not on the Extranet yet. Sign in on admin.booking.com, then click Save session.');
  }
  const state = await context.storageState();
  await piSavePortalSession('booking', state, job.by || 'in-app-connect');
  job._piSessionSaved = true;
  job.status = 'connected';
  job.updatedAt = Date.now();
  job.hint = 'Booking.com connected. You can Pull Booking.com now.';
  await piLoginCleanup(job, true);
}
async function piBookingInteractiveAdvance(job) {
  if (!job || !job.page || job._piFinishing) return;
  const page = job.page;
  try { if (page.isClosed && page.isClosed()) return; } catch (eClosed) { return; }
  if (await piBookingPageLooksLoggedIn(page)) {
    job._piFinishing = true;
    try {
      await piBookingFinishAndSave(job);
    } catch (eSave) {
      job._piFinishing = false;
      if (job._piSessionSaved) {
        job.status = 'connected';
        job.error = null;
        job.hint = 'Booking.com session saved. You can Pull Booking.com now.';
        job.updatedAt = Date.now();
        return;
      }
      job.status = 'interactive';
      job.error = null;
      await piAirbnbInteractiveSnapshot(job, 'Extranet was not confirmed yet. Keep signing in on admin.booking.com, then click Save session.');
    }
    return;
  }
  job.status = 'interactive';
  job.error = null;
  const snip = (await page.locator('body').innerText().catch(function () { return ''; })).replace(/\s+/g, ' ').slice(0, 320);
  job.pageSnippet = snip;
  await piAirbnbInteractiveSnapshot(job, 'Log into admin.booking.com below. When the Extranet / Finance is visible, click Save session for Pull.');
}
async function piBookingTryFillLogin(page) {
  const email = process.env.BOOKING_HOST_EMAIL || '';
  const pass = process.env.BOOKING_HOST_PASSWORD || '';
  if (!email || !pass) return;
  await page.waitForTimeout(800);
  for (const sel of ['button:has-text("Accept")', 'button:has-text("Agree")', '#onetrust-accept-btn-handler']) {
    const b = page.locator(sel).first();
    if (await b.count()) await b.click({ timeout: 2000 }).catch(function () {});
  }
  const emailInput = page.locator('#loginname, input[name="loginname"], input[type="email"]').first();
  if (!(await emailInput.count())) return;
  try {
    await emailInput.waitFor({ state: 'visible', timeout: 8000 });
    await emailInput.fill(email);
    await page.locator('button:has-text("Next"), button[type="submit"], button:has-text("Continue")').first().click({ timeout: 8000 }).catch(function () {});
    await page.waitForTimeout(2000);
    const passInput = page.locator('input[type="password"]:not([id="hidden-password"]), input[name="password"], #password').first();
    if (await passInput.count()) {
      await passInput.waitFor({ state: 'visible', timeout: 8000 });
      await passInput.fill(pass);
      await page.locator('button:has-text("Sign in"), button:has-text("Log in"), button:has-text("Sign In"), button[type="submit"]').first().click().catch(function () {});
      await page.waitForTimeout(2500);
    }
  } catch (eFill) {}
}
async function piBookingLoginWorker(job) {
  let pw;
  try { pw = require('playwright'); } catch (e) {
    job.status = 'error';
    job.error = 'playwright is not installed on this deploy';
    job.updatedAt = Date.now();
    return;
  }
  try {
    job.status = 'starting';
    job.hint = 'Opening admin.booking.com…';
    job.updatedAt = Date.now();
    const browser = await piAirbnbLaunchBrowser(pw);
    job.browser = browser;
    const context = await piAirbnbNewContext(browser);
    job.context = context;
    const page = await context.newPage();
    job.page = page;
    await page.goto('https://admin.booking.com/', { waitUntil: 'domcontentloaded', timeout: 90000 });
    await page.waitForTimeout(1500);
    await piBookingTryFillLogin(page);
    if (await piBookingPageLooksLoggedIn(page)) {
      await piBookingFinishAndSave(job);
      return;
    }
    job.status = 'interactive';
    job.error = null;
    job.hint = 'Log into admin.booking.com below. When the Extranet / Finance is visible, click Save session for Pull.';
    await piAirbnbInteractiveSnapshot(job);
  } catch (e) {
    job.status = 'error';
    job.error = e.message || String(e);
    job.updatedAt = Date.now();
    await piLoginCleanup(job, true);
  }
}
async function piBookingHarvestLiveJobs() {
  let saved = false;
  for (const job of _piLoginJobs.values()) {
    if (!job || String(job.channel || '') !== 'booking') continue;
    if (!job.page || !job.context) continue;
    if (job.status === 'error' || job.status === 'starting') continue;
    try {
      await piAirbnbRunBrowserAction(job, async function () {
        if (!(await piBookingPageLooksLoggedIn(job.page))) return;
        saved = (await piBookingSaveLiveSession(job)) || saved;
        try { await piBookingFinishAndSave(job); } catch (eSave) {
          if (job._piSessionSaved) {
            job.status = 'connected';
            job.error = null;
            job.hint = 'Booking.com session saved from the in-app browser. You can Pull Booking.com now.';
            job.updatedAt = Date.now();
          }
        }
      });
    } catch (eHarvest) {}
  }
  return saved;
}

app.post('/api/platform-invoices/sessions/booking/login', async (req, res) => {
  try {
    piLoginSweep();
    let playwrightOk = false;
    try { require.resolve('playwright'); playwrightOk = true; } catch (e) {}
    if (!playwrightOk) return res.status(503).json({ error: 'playwright is not installed on this deploy' });

    for (const job of _piLoginJobs.values()) {
      if (String(job.channel || '') !== 'booking') continue;
      if (job.status === 'starting' || job.status === 'logging_in' || job.status === 'interactive') {
        return res.json({ ok: true, job: piLoginPublic(job), resumed: true });
      }
    }
    const jobId = 'bk' + Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
    const job = {
      id: jobId,
      channel: 'booking',
      status: 'starting',
      error: null,
      hint: 'Opening admin.booking.com…',
      by: req.acctUser || (req.body && req.body.by) || '',
      createdAt: Date.now(),
      updatedAt: Date.now(),
      browser: null,
      context: null,
      page: null
    };
    _piLoginJobs.set(jobId, job);
    piBookingLoginWorker(job);
    res.json({ ok: true, job: piLoginPublic(job) });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

